import random

def get_girth(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_cycle = float('inf')
    for i in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[i] = 0
        queue = [i]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    min_cycle = min(min_cycle, dist[u] + dist[v] + 1)
    return min_cycle

def is_k_colorable(edges, n, k):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n
    def solve(u):
        if u == n:
            return True
        for c in range(k):
            if all(colors[v] != c for v in adj[u]):
                colors[u] = c
                if solve(u + 1):
                    return True
                colors[u] = -1
        return False
    return solve(0)

